'use strict';

const { validateRange } = require('./range.js');

// Prices a stay for the reservation form. Whatever the validator turns down is
// echoed back to the guest, so the reason has to read like a sentence.
function quoteStay(request) {
  const range = validateRange(request.checkIn, request.checkOut);
  if (!range.ok) {
    return { quoted: false, message: range.reason };
  }
  return {
    quoted: true,
    nights: range.nights,
    total: range.nights * request.nightlyRate,
  };
}

module.exports = { quoteStay };

